from collections import Counter
import string

class Solution:
    def smallestPalindrome(self, s: str) -> str:
        cnt = Counter(s)
        half = []
        mid = ""
        for ch in string.ascii_lowercase:
            v = cnt[ch] // 2
            if v > 0:
                half.append(ch * v)
            if cnt[ch] % 2 == 1:
                mid = ch
        left = "".join(half)
        return left + mid + left[::-1]

#include <string>
#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    string smallestPalindrome(string s) {
        vector<int> cnt(26, 0);
        for (char c : s) cnt[c - 'a']++;
        string left = "";
        string mid = "";
        for (int i = 0; i < 26; ++i) {
            int v = cnt[i] / 2;
            if (v > 0) left.append(v, 'a' + i);
            if (cnt[i] % 2 == 1) mid = string(1, 'a' + i);
        }
        string rev = left;
        reverse(rev.begin(), rev.end());
        return left + mid + rev;
    }
};

class Solution {
    public String smallestPalindrome(String s) {
        int[] cnt = new int[26];
        for (char c : s.toCharArray()) cnt[c - 'a']++;
        StringBuilder left = new StringBuilder();
        String mid = "";
        for (int i = 0; i < 26; i++) {
            int v = cnt[i] / 2;
            for (int k = 0; k < v; k++) left.append((char) ('a' + i));
            if (cnt[i] % 2 == 1) mid = String.valueOf((char) ('a' + i));
        }
        String lStr = left.toString();
        return lStr + mid + left.reverse().toString();
    }
}

var smallestPalindrome = function(s) {
    const cnt = new Array(26).fill(0);
    for (const c of s) cnt[c.charCodeAt(0) - 97]++;
    let left = "";
    let mid = "";
    for (let i = 0; i < 26; i++) {
        const v = Math.floor(cnt[i] / 2);
        if (v > 0) left += String.fromCharCode(97 + i).repeat(v);
        if (cnt[i] % 2 === 1) mid = String.fromCharCode(97 + i);
    }
    const rev = left.split("").reverse().join("");
    return left + mid + rev;
};
